<script setup>
import IconSprite from './components/IconSprite.vue';
import SvgIcon from './components/SvgIcon.vue';
import DominoTile from './components/DominoTile.vue';
import GoldenDiceButton from './components/GoldenDiceButton.vue';
import MatchConnections from './components/MatchConnections.vue';
import GameModal from './components/GameModal.vue';
import { probability } from './game/engine.js';
import { useDiceGame } from './composables/useDiceGame.js';
const {
  game,progress,today,history,busy,modal,selectedCell,probabilityAction,toastMessage,visualUpper,lastGain,lastNet,
  storageAvailable,soundOn,autoFlow,flowPauseReason,confetti,analysis,hasAnalysisLog,board,quote,selectedTarget,chosenProbability,rawProbability,
  ardor,canRoll,canDrop,activeTile,lockOptions,lastResult,rollTitle,dropTitle,legendCombo,legendId,targetPrize,actionCost,
  COMBINATIONS,PROBABILITY_TARGETS,format,percent,signed,perform,selectCell,purchaseLock,releaseLock,changeTarget,
  showAnalysis,showLegend,finish,requestFinish,requestNew,startNew,toggleSound,toggleAutoFlow,exportLog,
}=useDiceGame();
const matched=(row,i)=>board.value.matches.some(m=>row==='upper'?m.upperIndex===i:m.lowerIndices.includes(i));
const dateLabel=v=>new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const duration=ms=>`${Math.floor(ms/60000)} мин ${Math.floor(ms%60000/1000)} с`;
const comboLabel=id=>COMBINATIONS.find(c=>c.id===id)?.label||'Совпадение';
function viewSession(s){analysis.value=s;modal.value='analysis';}
const legendChance=action=>probability(game,action,legendId.value==='single'?'any':legendId.value);
</script>
<template>
  <IconSprite />
  <div class="app-shell">
    <header class="topbar">
      <a href="./" class="brand" title="Dice’n’Roll — сколько дайсов ты набьёшь сегодня? Кошелёк сохраняется между сессиями."><span class="brand-dice"><SvgIcon name="dice" /></span><span>dice<span class="brand-n">’n’</span>roll<span class="brand-dot">.</span></span></a>
      <span class="header-caption">БОЛЬШЕ АЗАРТА. БОЛЬШЕ ДАЙСОВ.</span>
      <nav class="header-actions" aria-label="Меню игры">
        <button class="quiet-button sound-button" :title="soundOn?'Выключить звук':'Включить звук'" :aria-label="soundOn?'Выключить звук':'Включить звук'" @click="toggleSound"><SvgIcon :name="soundOn?'sound':'mute'" /></button>
        <button class="quiet-button" title="Все собранные комбинации: за сегодня и за всё время. Хранятся в этом браузере." @click="modal='collection'"><SvgIcon name="cup" /><span>Коллекция</span></button>
        <button class="quiet-button" title="Как связаны Ardor, цена хода, фиксации и награды" @click="modal='rules'"><SvgIcon name="info" /><span>Как играть</span></button>
      </nav>
    </header>
    <main>
      <section class="hero">
        <div><div class="eyebrow"><span class="live-dot" /> ОДИН КОШЕЛЁК. КАЖДЫЙ ХОД ИМЕЕТ ЦЕНУ.</div><h1>Сколько дайсов <em>набьёшь сегодня?</em></h1><p>Контроль стоит дайсов. Азарт увеличивает награды.</p></div>
        <div class="hero-right"><span class="save-status" :title="storageAvailable?'Кошелёк, коллекция и текущая сессия сохранены в LocalStorage. Новый стол не обнуляет баланс.':'Браузер не разрешил сохранить данные; прогресс может потеряться после закрытия.'"><span class="live-dot" />{{storageAvailable?'Кошелёк сохранён':'Не удалось сохранить'}}</span><button class="text-button" :disabled="!!busy" title="Сохранить итог сессии, список комбинаций и статистику пар" @click="requestFinish">{{game.phase==='finished'?'Итоги сессии':'Забрать итог'}} <SvgIcon name="arrow" /></button></div>
      </section>
      <section class="daily-ribbon" aria-label="Успехи за сегодня">
        <div title="Все награды за комбинации сегодня. Дневной запас сюда не входит."><span>ВЫИГРАНО СЕГОДНЯ</span><strong id="today-earned">+{{format(today.earnedDice)}} <small>дайсов</small></strong></div>
        <div title="Выигрыши минус расходы на Roll, Drop и фиксации за сегодня. Дневной запас не считается заработком."><span>ЧИСТЫЙ РЕЗУЛЬТАТ</span><strong id="today-net" :class="{negative:today.netDice<0}">{{signed(today.netDice)}} <small>дайсов</small></strong></div>
        <div title="Стартовый запас выдаётся один раз в местные календарные сутки. Перезагрузка и новая сессия его не повторяют."><span>ЗАПАС ДНЯ</span><strong>+{{today.grant}} <small>раз в сутки</small></strong></div>
        <button class="text-button" title="Открыть сохранённую коллекцию всех комбинаций" @click="modal='collection'">Мои успехи <SvgIcon name="arrow" /></button>
      </section>
      <div class="play-layout">
        <section class="arena" aria-label="Барабаны и FIFO-карусель">
          <div class="arena-top"><div class="table-label"><span class="live-dot" /> СТОЛ № 01 <span class="table-divider">/</span> <span>DOMINO POKER</span></div><button class="text-button" :disabled="!!busy" title="Открыть новый стол с тем же кошельком. Новые дайсы не выдаются." @click="requestNew"><SvgIcon name="roll" /> Новый стол</button></div>
          <div class="table-body">
            <div class="machine">
              <MatchConnections v-if="!busy" :matches="board.matches" :upper="game.upper" />
              <div class="row-heading"><span><b>01</b> ВЕРХНИЕ БАРАБАНЫ</span><span title="Фиксация удерживает пару, снижает Ardor и награды, увеличивает цену Roll."><SvgIcon name="unlock" /> Удержание меняет цену игры</span></div>
              <div class="upper-strip" aria-label="Верхние барабаны"><DominoTile v-for="(tile,index) in (visualUpper||game.upper)" :key="index" :tile="tile" row="upper" :index="index" :matched="!busy&&matched('upper',index)" :paid="game.awardedUpperIds.includes(tile.id)" :active="selectedCell?.row==='upper'&&selectedCell.index===index" :busy="!!busy||game.phase==='finished'" :rolling="busy==='roll'" @select="selectCell" /></div>
              <div class="control-bridge">
                <button id="roll-button" :class="['roll-button',{'is-rolling':busy==='roll'}]" :disabled="!canRoll" :title="rollTitle" @click="perform('roll')"><SvgIcon name="roll" /><span>{{busy==='roll'?'Крутим…':'Roll the Dice'}}<small>−{{quote.rollCost??'—'}} дайсов из кошелька</small></span><kbd>R</kbd></button>
                <div class="bridge-stat" :title="`Баланс ${game.diceCredits} ÷ цена Roll ${quote.rollCost??'все закреплены'}. Лимита 50 больше нет.`"><span>МОЖНО ROLL</span><strong id="rolls-left">{{quote.availableRolls}}<small>по {{quote.rollCost??'—'}}</small></strong></div>
                <div class="bridge-stat" :title="dropTitle"><span>ЦЕНА DROP</span><strong id="drop-cost">{{quote.dropCost??'—'}}<small>дайс.</small></strong></div>
              </div>
              <div class="row-heading lower-heading"><span><b>02</b> НИЖНЯЯ КАРУСЕЛЬ <span class="fifo-tag">FIFO</span></span><button id="auto-flow" :class="['auto-flow-button',{active:autoFlow}]" :aria-pressed="autoFlow" :disabled="!!busy||game.phase==='finished'" title="Автопоток делает Drop каждые 5 секунд по текущей цене. 3 закреплённые нижние пары = 3 дайса за шаг. В скрытой вкладке и открытых окнах ждёт." @click="toggleAutoFlow"><span />{{autoFlow?(flowPauseReason?'Авто · ждёт Roll':'Автопоток · вкл'):'Автопоток'}}</button></div>
              <div class="carousel-viewport"><TransitionGroup name="fifo" tag="div" class="lower-strip" aria-label="Нижняя FIFO-карусель"><DominoTile v-for="(tile,index) in game.lower" :key="tile.id" :tile="tile" row="lower" :index="index" :matched="!busy&&matched('lower',index)" :active="selectedCell?.row==='lower'&&selectedCell.index===index" :busy="!!busy||game.phase==='finished'" @select="selectCell" /></TransitionGroup></div>
              <div class="carousel-track" aria-hidden="true"><span>← OUT</span><span>ПЯТЬ ИЗВЕСТНЫХ. ОДНА НОВАЯ.</span><span>IN ←</span></div>
            </div>
            <aside class="table-side">
              <div class="score-display wallet-display" title="Единый баланс. Roll, Drop и фиксации списывают дайсы; комбинации добавляют их сюда же. Кошелёк сохраняется между столами и днями."><span class="eyebrow"><SvgIcon name="dice" /> ТВОЙ КОШЕЛЁК</span><strong id="total-score">{{format(game.diceCredits)}}</strong><span class="wallet-unit">ДАЙСОВ</span><span v-if="lastResult?.type!=='ready'" :class="['score-gain',{negative:lastNet<0}]">{{signed(lastNet)}} за последний ход</span><div class="personal-best" title="Награды текущей сессии без дневного запаса">За сессию <b>+{{format(game.total)}}</b></div></div>
              <div class="drop-area"><span class="drop-kicker">ТЕКУЩАЯ ЦЕНА −{{quote.dropCost??'—'}} ДАЙС.</span><GoldenDiceButton :disabled="!canDrop" :busy="busy==='drop'" :credits="game.diceCredits" :cost="quote.dropCost||1" :title="dropTitle" @click="perform('drop')" /><span class="drop-key"><kbd>D</kbd> или нажми на золотые кости</span></div>
            </aside>
          </div>
          <div class="result-strip" aria-live="polite"><span :class="['result-mark',{won:lastGain}]">{{lastGain?'✦':'↗'}}</span><div><strong>{{busy?'Кости в движении…':game.phase==='finished'?'Сессия сохранена. Кошелёк остаётся с тобой.':lastResult?.type==='ready'?'Один ресурс. Твоя стратегия. Сколько набьёшь?':lastGain?`${lastResult.combo.label}: +${format(lastGain)} дайсов · чистыми ${signed(lastNet)}`:`Без новой награды: ${signed(lastNet)} дайсов`}}</strong><span>{{board.cards.length}} совпавших верхних фишек <i>·</i> {{board.combo.label}} <i>·</i> награды при Ardor хода</span></div><button class="text-button" title="Открыть яркую таблицу наград и объяснение каждой комбинации" @click="modal='collection'">Награды <SvgIcon name="arrow" /></button></div>
          <div v-if="selectedCell&&activeTile" class="lock-popover" role="region" aria-label="Фиксация ячейки">
            <div class="lock-popover-heading"><SvgIcon name="lock" /><div><strong>{{selectedCell.row==='upper'?'Барабан':'Нижняя ячейка'}} {{selectedCell.index+1}} · {{activeTile.a}} : {{activeTile.b}}</strong><span>{{activeTile.lockRemaining?`Ещё ${activeTile.lockRemaining} ${selectedCell.row==='upper'?'Roll':'Drop'}`:'Цена хода вырастет, Ardor и награды снизятся'}}</span></div><button class="icon-button" title="Закрыть фиксацию" aria-label="Закрыть фиксацию" @click="selectedCell=null"><SvgIcon name="close" /></button></div>
            <div v-if="!activeTile.lockRemaining" class="lock-offers"><button v-for="offer in lockOptions" :key="offer.duration" :disabled="game.diceCredits<offer.cost" :title="`${offer.label} за ${offer.cost} дайс. из кошелька. Срок уменьшается только от действий этого ряда. Влияет на Ardor, цену и награды.`" @click="purchaseLock(offer.duration)"><span>{{offer.label}}</span><b>−{{offer.cost}} дайс.</b></button></div><button v-else class="release-button" title="Бесплатно снять фиксацию. Ardor, награды и цены пересчитаются; потраченное не возвращается." @click="releaseLock">Освободить бесплатно <SvgIcon name="unlock" /></button>
          </div>
        </section>
        <aside class="insights-column">
          <section class="ardor-card">
            <div class="insight-heading"><span class="eyebrow">ARDOR INDEX</span><SvgIcon name="flame" /></div><h2>Риск задаёт<br><em>награду.</em></h2>
            <div class="ardor-reading" title="Ardor = 100 × (12 − число всех фиксаций) / (12 + сила удержанной комбинации). Сильнее удержанная комбинация — больше контроля. Это уровень открытого риска и множитель наград; точные вероятности показаны отдельно."><strong id="ardor-index">{{ardor.toFixed(1)}}</strong><span>/ 100</span></div>
            <div class="ardor-gauge" title="Меньше фиксаций — больше свободы, выше Ardor и награды; Roll дешевле."><span :style="{width:`${ardor}%`}" /></div><div class="gauge-labels"><span>Больше контроля</span><span>Больше награды</span></div>
            <div class="economy-explainer"><span>{{quote.locked}} / 12 закреплено</span><b>Награды ×{{quote.scale.toFixed(2)}}</b></div>
            <label class="target-label" for="probability-target">ПРИЦЕЛЬСЯ В КОМБИНАЦИЮ</label><select id="probability-target" :value="game.target" :disabled="!!busy||game.phase==='finished'" :title="selectedTarget.description+' Выбор цели — просмотр шансов; он не меняет цену или награду.'" @change="changeTarget($event.target.value)"><option v-for="target in PROBABILITY_TARGETS" :key="target.id" :value="target.id">{{target.label}}</option></select>
            <div class="probability-tabs" role="group" aria-label="Ход для расчёта"><button :class="{active:probabilityAction==='roll'}" title="Точный шанс цели после следующего Roll" @click="probabilityAction='roll'">Следующий Roll</button><button :class="{active:probabilityAction==='drop'}" title="Точный шанс цели после следующего Drop" @click="probabilityAction='drop'">Следующий Drop</button></div>
            <div class="chance-line" :title="selectedTarget.description+' Требуется новое, ещё не оплаченное совпадение.'"><span>Точный шанс цели</span><strong id="target-chance">{{percent(chosenProbability)}}</strong></div>
            <div class="risk-reward"><div title="Столько спишется без новой награды. Выплата может быть меньше цены — это тоже чистый проигрыш."><span>Без награды</span><b>−{{actionCost??'—'}}</b></div><button title="Минимальная награда за выбранную цель при одной новой совпавшей фишке. Больше новых совпадений увеличит её. Нажми для легенды." @click="showLegend(game.target==='any'?'single':game.target)"><span>За цель — от</span><b>+{{targetPrize}}</b></button></div>
            <div class="chance-line subtle" title="Точный шанс любой новой выплаты, независимо от выбранной цели. Это не вероятность чистой прибыли."><span>Любая новая награда</span><span>{{percent(rawProbability)}}</span></div><p class="odds-note">Фиксируешь — платишь за контроль.<br>Отпускаешь — играешь за больший приз.</p>
          </section>
          <section class="move-card"><div class="insight-heading"><span class="eyebrow">ВСЁ СВЯЗАНО</span><span>✳</span></div><h3>Один кошелёк.<br>Два способа рискнуть.</h3><p>Roll стоит {{quote.rollCost??'—'}}, Drop — {{quote.dropCost??'—'}}. Сейчас хватит на {{quote.availableRolls}} полных Roll или {{quote.availableDrops}} Drop. Любая награда возвращается в игру.</p><div><span title="При 3 нижних фиксациях каждый Drop стоит 3 дайса, пока срок фиксаций не истечёт.">3 НИЖНИХ ФИКСАЦИИ → DROP ЗА 3</span><SvgIcon name="lock" /></div></section>
        </aside>
      </div>
      <section class="bottom-panels">
        <div class="combination-panel"><div class="section-heading"><div><span class="eyebrow">ЗАРАБАТЫВАЙ И СОБИРАЙ</span><h2>Комбинации при Ardor {{ardor.toFixed(1)}}</h2></div><button class="text-button" title="Все награды, дневные успехи и коллекция за всё время" @click="modal='collection'">Все 13 <SvgIcon name="arrow" /></button></div><div class="combo-shortlist"><button v-for="combo in COMBINATIONS.filter(c=>['pair','straight','full-house','royal'].includes(c.id))" :key="combo.id" :title="combo.description+` Сейчас бонус ${quote.prizes[combo.id]} дайсов плюс ${quote.prizes.single} за каждое новое совпадение. Нажми для легенды.`" @click="showLegend(combo.id)"><span class="combo-mini-symbol">{{combo.id==='pair'?'Ⅱ':combo.id==='straight'?'↗':combo.id==='full-house'?'ⅢⅡ':'♛'}}</span><strong>{{combo.label}}</strong><span class="prize-value">+{{format(quote.prizes[combo.id])}} <small>дайс.</small></span><span class="combo-count">{{progress.collection[combo.id]||0}} в коллекции</span></button></div></div>
        <div class="session-mini"><div class="section-heading"><div><span class="eyebrow">ЗА ЭТУ СЕССИЮ</span><h2>Набито +{{format(game.total)}} · потрачено {{format(game.spentDice)}}</h2></div><button class="icon-button" title="Комбинации, прибыль и пары, которые чаще совпадали или не совпадали" @click="showAnalysis"><SvgIcon name="chart" /></button></div><div class="session-mini-stats"><div><b>{{game.rolls}}</b><span>Roll</span></div><div><b>{{game.drops}}</b><span>Drop</span></div><div><b>{{game.locksPurchased}}</b><span>Фиксаций</span></div><div :class="{negative:game.total-game.spentDice<0}"><b>{{signed(game.total-game.spentDice)}}</b><span>Чистыми</span></div></div></div>
      </section>
      <footer><span>Dice’n’Roll <i>·</i> Сколько набил сегодня?</span><button class="text-button" title="История сессий и их подробные итоги" @click="modal='records'">История сессий</button><button class="text-button" title="Скачать кошелёк, коллекцию, сессию и журнал в JSON" @click="exportLog"><SvgIcon name="save" /> Экспорт успехов</button></footer>
    </main>
  </div>
  <GameModal :open="!!modal" @close="modal=''">
    <template v-if="modal==='rules'"><span class="modal-kicker">ПРОСТАЯ ИДЕЯ</span><h2 id="modal-title">Набей больше дайсов,<br>чем потратишь.</h2><div class="rules-steps"><div><b>01</b><section><h3>Дайсы — это всё</h3><p>Каждый день один раз получаешь 120 стартовых дайсов. Roll, Drop и фиксации тратят общий кошелёк; новые совпадения и комбинации пополняют его. Новый стол и перезагрузка запас не повторяют.</p></section></div><div><b>02</b><section><h3>Меньше контроля — выше награды</h3><p>Без фиксаций Ardor = 100, Roll стоит 6, Drop — 1. Каждая фиксация снижает Ardor. Удержанная сильная комбинация снижает его дополнительно. Roll дороже при меньшем Ardor: цена = 600 / индекс с округлением вверх.</p></section></div><div><b>03</b><section><h3>Drop дорожает от нижних фиксаций</h3><p>0 или 1 закреплённая нижняя пара: Drop стоит 1 дайс. 2 пары: 2. 3 пары: 3, и так далее. Все шесть закреплены — сначала освободи одну. Срок фиксаций уменьшается только от действий своего ряда.</p></section></div><div><b>04</b><section><h3>Совпало — дайсы твои</h3><p>Два одинаковых числа между рядами совпадают в любом порядке. Каждая новая совпавшая верхняя фишка приносит награду, плюс бонус самой сильной комбинации на поле. Награда = базовая × Ardor / 100 с округлением вверх. Уже оплаченная фишка повторно не приносит награду.</p></section></div></div><p>Масть и верхнее число совпавшей верхней фишки образуют «карту». Стриты, флеши, фулл-хаусы и другие комбинации приносят разное число дайсов. Все условия и выплаты — по клику на комбинацию.</p><p>Точный шанс показан отдельно от Ardor. Малая награда может не окупить ход: смотри чистый результат. История пар описывает прошлые совпадения, а не предсказывает следующие.</p><button class="modal-primary" @click="modal=''" title="Вернуться к игре">Поймать свои дайсы <SvgIcon name="arrow" /></button></template>
    <template v-else-if="modal==='collection'||modal==='combinations'"><span class="modal-kicker">ТВОИ УСПЕХИ СОХРАНЯЮТСЯ</span><h2 id="modal-title">Каждая комбинация —<br>ещё дайсы в кошелёк.</h2><p>Показаны награды при текущем Ardor {{ardor.toFixed(1)}}. Бонус одной старшей комбинации складывается с {{quote.prizes.single}} дайс. за каждую новую совпавшую фишку. Нажми на строку для легенды и шансов.</p><div class="collection-totals"><span>Сегодня выиграно <b>+{{format(today.earnedDice)}}</b></span><span>За всё время <b>+{{format(progress.earnedDice)}}</b></span></div><div class="collection-list"><button v-for="combo in COMBINATIONS" :key="combo.id" :title="combo.description+` База ${combo.baseDice}, сейчас ${quote.prizes[combo.id]} дайсов. Нажми для объяснения.`" @click="showLegend(combo.id)"><span><strong>{{combo.label}}</strong><small>Сегодня {{today.combinationCounts[combo.id]||0}} · Всего {{progress.collection[combo.id]||0}}</small></span><b>+{{format(quote.prizes[combo.id])}}<small>дайс.{{combo.id==='single'?' / фишка':''}}</small></b><SvgIcon name="arrow" /></button></div><button class="modal-primary" title="Вернуться к игровому столу" @click="modal=''">Собирать дальше</button></template>
    <template v-else-if="modal==='legend'"><span class="modal-kicker">ЛЕГЕНДА КОМБИНАЦИИ</span><h2 id="modal-title">{{legendCombo.label}}<span class="accent">.</span></h2><p>{{legendCombo.description}}</p><div class="legend-prize"><strong>+{{format(quote.prizes[legendId])}}</strong><span>ДАЙСОВ {{legendId==='single'?'ЗА КАЖДУЮ НОВУЮ ФИШКУ':'БОНУСА ЗА КОМБИНАЦИЮ'}}</span></div><p>База {{legendCombo.baseDice}} × Ardor {{quote.rawArdor.toFixed(4)}}% = {{quote.prizes[legendId]}} с округлением вверх (индекс для расчёта не округляется). {{legendId==='single'?'Это награда за каждое новое совпадение.':`Плюс ${quote.prizes.single} дайс. за каждую новую совпавшую верхнюю фишку. Выплачивается только один старший бонус.`}}</p><div class="legend-odds"><div><span>Шанс через Roll</span><b>{{percent(legendChance('roll'))}}</b><small>Цена −{{quote.rollCost??'—'}}</small></div><div><span>Шанс через Drop</span><b>{{percent(legendChance('drop'))}}</b><small>Цена −{{quote.dropCost??'—'}}</small></div></div><div class="legend-owned"><span>Сегодня <b>×{{today.combinationCounts[legendId]||0}}</b></span><span>В коллекции <b>×{{progress.collection[legendId]||0}}</b></span></div><p class="analysis-note">Для выплаты нужно хотя бы одно новое совпадение. Вероятность означает наличие комбинации, включая более сильные варианты с тем же условием. Реальная награда фиксируется по Ardor до хода.</p><button class="modal-primary" title="Вернуться к таблице всех наград" @click="modal='collection'">Все награды</button><button class="modal-secondary" title="Вернуться к игровому столу" @click="modal=''">В игру</button></template>
    <template v-else-if="modal==='records'"><span class="modal-kicker">ЛОКАЛЬНАЯ ИСТОРИЯ</span><h2 id="modal-title">Твой путь<br>в дайсах.</h2><p>Кошелёк и коллекция общие для всех сессий. Здесь — последние 20 итогов.</p><div v-if="!history.length" class="empty-history">Сделай первый ход — появится первая история.</div><button v-for="item in history" :key="item.sessionId" class="history-session" title="Комбинации, чистый результат и статистика пар этой сессии" @click="viewSession(item)"><span class="history-symbol"><SvgIcon name="dice" /></span><span><strong>Набито +{{format(item.earnedDice)}}</strong><small>{{dateLabel(item.startedAt)}} · {{item.final?'Завершена':'Сохранена'}}</small></span><b :class="{negative:item.netDice<0}">{{signed(item.netDice)}}</b><SvgIcon name="arrow" /></button><button class="modal-primary" @click="modal=''" title="Вернуться к игре">Продолжить</button></template>
    <template v-else-if="modal==='finish'||modal==='new'"><span class="modal-kicker">УСПЕХИ ОСТАНУТСЯ С ТОБОЙ</span><h2 id="modal-title">{{modal==='new'?'Открыть новый стол?':'Забрать итог сессии?'}}</h2><p>Выиграно {{format(game.total)}}, потрачено {{format(game.spentDice)}}, чистыми {{signed(game.total-game.spentDice)}} дайсов. Сохраним комбинации и статистику пар. В кошельке останется {{format(game.diceCredits)}} — новый стол не выдаёт запас заново.</p><button id="confirm-finish" class="modal-primary" @click="modal==='new'?startNew():finish()" title="Сохранить итог и коллекцию">{{modal==='new'?'Сохранить и открыть стол':'Сохранить и посмотреть итог'}} <SvgIcon name="arrow" /></button><button class="modal-secondary" @click="modal=''" title="Вернуться к текущей игре">Ещё поиграю</button></template>
    <template v-else-if="modal==='analysis'&&analysis"><span class="modal-kicker">ИТОГ ПОСЛЕДНЕЙ СЕССИИ</span><h2 id="modal-title">Набил +{{format(analysis.earnedDice)}}<span class="accent"> дайсов.</span></h2><p>Потрачено {{format(analysis.spentDice)}} · Чистыми <b :class="{negative:analysis.netDice<0}">{{signed(analysis.netDice)}}</b> · {{duration(analysis.durationMs)}}. Кошелёк и коллекция сохранены.</p><div class="analysis-grid"><div><b>{{analysis.rolls}} / {{analysis.drops}}</b><span>Roll / Drop</span></div><div><b>{{percent(analysis.hitRate)}}</b><span>Ходов с наградой</span></div><div><b>{{Number(analysis.meanArdor).toFixed(1)}}</b><span>Средний Ardor</span></div></div><div class="analysis-combos"><span class="eyebrow">СОБРАНО ЗА СЕССИЮ</span><span v-if="!Object.keys(analysis.combinationCounts||{}).length">Пока без новых комбинаций</span><span v-for="(count,id) in analysis.combinationCounts" :key="id">{{comboLabel(id)}} <b>×{{count}}</b></span></div><div class="pair-report"><section><h3>Чаще совпадали</h3><p v-if="!analysis.lucky?.length">Пока нет успешных совпадений.</p><div v-for="p in analysis.lucky" :key="p.key"><strong>{{p.key.replace(':',' · ')}}</strong><span>{{p.hits}} из {{p.attempts}} · {{percent(p.rate)}}</span></div></section><section><h3>Чаще не совпадали</h3><p v-if="!analysis.unlucky?.length">Пока нет неудачных проверок.</p><div v-for="p in analysis.unlucky" :key="p.key"><strong>{{p.key.replace(':',' · ')}}</strong><span>{{p.hits}} из {{p.attempts}} совпали</span></div></section></div><p v-if="analysis.automaticDrops" class="analysis-note">Автопоток сделал {{analysis.automaticDrops}} из {{analysis.drops}} Drop; они отдельно помечены в журнале.</p><p class="analysis-note">Это наблюдения этой сессии, не прогноз. Проверка — одна ещё не оплаченная верхняя фишка после хода. Показаны успешные проверки из всех попыток. Общая коллекция сохраняется между сессиями в этом браузере; подробные журналы — для трёх последних сессий.</p><button class="modal-secondary" :disabled="!hasAnalysisLog" title="Скачать подробный журнал этой сессии, если он ещё хранится" @click="exportLog"><SvgIcon name="save" /> Журнал JSON</button><button class="modal-primary" @click="game.phase==='finished'?startNew():modal=''" title="Продолжить с сохранённым кошельком">{{game.phase==='finished'?'Новый стол с тем же кошельком':'Продолжить сессию'}} <SvgIcon name="arrow" /></button></template>
  </GameModal>
  <div id="toast" :class="['toast',{show:toastMessage}]" role="status">{{toastMessage}}</div><div id="confetti" aria-hidden="true"><span v-for="piece in confetti" :key="piece.id" class="confetto" :style="piece.style" /></div>
</template>
